function addFooter(slide, srcText) {
  slide.addText("Source: METR (2025) · arXiv:2503.14499", {
    x: 0.4, y: 5.38, w: 9.2, h: 0.22,
    fontSize: 8, color: C.slate, italic: true,
  });
}

