const pptxgen = require("pptxgenjs");
const path = require("path");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Measuring AI Ability to Complete Long Software Tasks";
pres.author = "METR";

// ─── Color palette: Midnight Executive with amber accent ──────────────────────
const C = {
  navy:     "1B2A4A",
  navyMid:  "243352",
  navyDark: "111827",
  ice:      "CADCFC",
  iceLight: "E8F0FE",
  amber:    "F59E0B",
  amberLt:  "FEF3C7",
  white:    "FFFFFF",
  offWhite: "F8FAFC",
  slate:    "64748B",
  slateLt:  "94A3B8",
  text:     "1E293B",
  textMuted:"475569",
  gridLine: "CBD5E1",
  teal:     "0D9488",
  tealLt:   "CCFBF1",
};

// ─── Helpers ──────────────────────────────────────────────────────────────────
const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.14 });

function addFooter(slide, srcText) {
  slide.addText("Source: METR (2025) · arXiv:2503.14499", {
    x: 0.4, y: 5.38, w: 9.2, h: 0.22,
    fontSize: 8, color: C.slate, italic: true,
  });
}

// ═══════════════════════════════════════════════════════════════════════════════
// SLIDE 1 — Title
// ═══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.navyDark };

  // Ambient glow orb (top-right)
