  const takeaways = [
    {
      num: "1",
      text: "The 50% time horizon is a robust, intuitive metric — R² = 0.97 over 6 years of model releases.",
    },
    {
      num: "2",
      text: "Doubling every ~7 months, with possible acceleration since 2024 — capability growth is not slowing.",
    },
    {
      num: "3",
      text: "Frontier models (o3) autonomously complete ~2 hours of human-equivalent software work — up from 2 seconds for GPT-2 in 2019.",
    },
    {
      num: "4",
      text: "External validity remains open — benchmark tasks may not fully represent average real-world intellectual labor distributions.",
    },
    {
      num: "5",
      text: "Key capability drivers: reasoning, tool use, error recovery. Key limitations: unstructured tasks, uncertain generalization.",
    },
  ];

  const startY = 1.0;
  const rowH = 0.82;
  const gap = 0.1;

  takeaways.forEach((t, i) => {
    const y = startY + i * (rowH + gap);

    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.4, y, w: 9.2, h: rowH,
      fill: { color: C.navyMid, transparency: 30 },
    });

    // Number badge
    s.addShape(pres.shapes.OVAL, {
      x: 0.55, y: y + 0.16, w: 0.5, h: 0.5,
      fill: { color: C.amber },
    });
    s.addText(t.num, {
      x: 0.55, y: y + 0.16, w: 0.5, h: 0.5,
      fontSize: 14, fontFace: "Arial Black", color: C.navyDark,
      align: "center", valign: "middle",
    });

    s.addText(t.text, {
      x: 1.22, y: y + 0.12, w: 8.2, h: rowH - 0.24,
      fontSize: 12, fontFace: "Arial", color: C.white,
      valign: "middle",
    });
  });

  // Closing call to action
  s.addShape(pres.shapes.LINE, {
    x: 0.4, y: 5.15, w: 9.2, h: 0,
    line: { color: C.amber, width: 1.5 },
  });
  s.addText("Exponential autonomous capability growth demands proactive safety governance — not reactive oversight.", {
    x: 0.4, y: 5.22, w: 9.2, h: 0.35,
    fontSize: 11, fontFace: "Georgia", color: C.ice, italic: true,
  });
}

// ─── Write file ───────────────────────────────────────────────────────────────
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
.then(() => console.log("✓ Saved /app/output/final_deck.pptx"))
